/** Every key, archived included — issue numbers of archived projects carry it. */
export async function listTakenProjectKeys(
  orgId: OrgId,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ key: projects.key })
    .from(projects)
    .where(orgPredicate(projects.orgId, orgId))
    .all();
  return rows.map((row) => row.key);
}

/** Live issues that are neither done nor canceled. */
export async function countOpenIssues(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        ...compact(livePredicate(issues.archivedAt, {})),
        notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
      ),
    )
    .get();
  return row?.value ?? 0;
}""")
