sub('lib/slug.ts',"/** Project keys are","""/** Makes `key` unique among `taken` by appending a number, within four characters. */
export function uniqueProjectKey(key: string, taken: Iterable<string>): string {
  const used = new Set([...taken].map((k) => k.toUpperCase()));
  const base = key.toUpperCase();
  if (!used.has(base)) return base;
  for (let n = 2; n < 10_000; n += 1) {
    const suffix = String(n);
    const candidate = `${base.slice(0, Math.max(1, 4 - suffix.length))}${suffix}`;
    if (!used.has(candidate)) return candidate;
  }
  throw new InvalidSlugError(key, "exhausted unique key suffixes");
}

